"""", "originalFile": """"Transactional key-value store backing the booking flow.

The isolation level (config transaction.isolation) decides whether a transaction can see another
transaction's UNCOMMITTED writes:
  - read_uncommitted (engine default): uncommitted writes ARE visible to others -> a dirty read.
  - read_committed: only committed values are visible to other transactions -> no dirty read.
NOTE (pre-fix): the default is read_unmitted, so a fixed interleaved trace observes a dirty read.
"""


class TransactionStore:
    def __init__(self, isolation="read_uncommitted"):
        self.isolation = isolation
        self._committed = {}
        self._uncommitted = {}   # txn_id -> {key: value}

    def begin(self, txn_id):
        self._uncommitted[txn_id] = {}

    def write(self, txn_id, key, value):
        self._uncommitted.setdefault(txn_id, {})[key] = value

    def read(self, txn_id, key):
        # a transaction always sees its own writes
        own = self._uncommitted.get(txn_id, {})
        if key in own:
            return own[key]
        # dirty reads: at read_unmitted, others' uncommitted writes are visible
        if self.isolation == "read_uncommitted":
            for other, writes in self._uncommitted.items():
                if other != txn_id and key in writes:
                    return writes[key]
        return self._committed.get(key)

    def commit(self, txn_id):
        writes = self._uncommitted.pop(txn_id, {})
        self._committed.update(writes)
        return writes

    def rollback(self, txn_id):
        self._uncommitted.pop(txn_id, None)


def make_store():
    from .config import load_config
    cfg = load_config()
    isolation = cfg.get("transaction", {}).get("isolation", "read_uncommitted")
    return TransactionStore(isolation)
